// MCPServer What may be shown about a source: never a secret value.
type MCPServer struct {
	AddedAt       time.Time  `json:"added_at"`
	AllowSampling bool       `json:"allow_sampling"`
	AlwaysOffer   bool       `json:"always_offer"`
	Args          *[]string  `json:"args,omitempty"`
	CheckedAt     *time.Time `json:"checked_at,omitempty"`
	Command       *string    `json:"command,omitempty"`
	Description   *string    `json:"description,omitempty"`
	Enabled       bool       `json:"enabled"`
	Env           []struct {
		Key    string `json:"key"`
		Secret bool   `json:"secret"`
		Value  string `json:"value"`
	} `json:"env"`
	Error        *string `json:"error,omitempty"`
	HasPrompts   bool    `json:"has_prompts"`
	HasResources bool    `json:"has_resources"`
	Headers      []struct {
		Key    string `json:"key"`
		Secret bool   `json:"secret"`
		Value  string `json:"value"`
	} `json:"headers"`
	Id           string     `json:"id"`
	Instructions *string    `json:"instructions,omitempty"`
	Keywords     []string   `json:"keywords"`
	LastUsed     *time.Time `json:"last_used,omitempty"`

	// Missing `missing` names a program this source needs that is not installed, such as Node.js.
	Missing       *string `json:"missing,omitempty"`
	Name          string  `json:"name"`
	Preset        *string `json:"preset,omitempty"`
	Protocol      *string `json:"protocol,omitempty"`
	Running       bool    `json:"running"`
	ServerName    *string `json:"server_name,omitempty"`
	ServerVersion *string `json:"server_version,omitempty"`
	SignedIn      *bool   `json:"signed_in,omitempty"`

	// Status Ready, sign_in, error, or off.
	Status string `json:"status"`
	Tools  []struct {
		Changed     bool   `json:"changed"`
		Description string `json:"description"`
		Enabled     bool   `json:"enabled"`
		Id          string `json:"id"`
		Name        string `json:"name"`

		// Policy Allow or ask; Changed is true when the person set it.
		Policy     string `json:"policy"`
		RemoteName string `json:"remote_name"`
		Risk       string `json:"risk"`
	} `json:"tools"`
	Url *string `json:"url,omitempty"`

	// Where "local" for a program on this computer, "remote" for a web address.
	Where string `json:"where"`
}

// Me Who the request is from (#206): a Principal, with the profiles and capabilities they have.
type Me struct {
	// Capabilities What someone may use (#589): each capability, on or off, so an app hides what they can't.
	Capabilities Capabilities `json:"capabilities"`
	KeyId        *string      `json:"key_id,omitempty"`
	KeyProfile   *string      `json:"key_profile,omitempty"`

	// Person Someone who uses this computer (#206).
	Person Person `json:"person"`

	// Profiles The profiles they may chat with, when they're pinned to some (#345)
	Profiles *[]string `json:"profiles,omitempty"`

	// Via Known values: `this_computer`, `api_key`, `session`, `proxy`, `none`, `system`; others may be added.
	Via string `json:"via"`
}

// Memory One durable fact or preference.
type Memory struct {
	Category  string    `json:"category"`
	Content   string    `json:"content"`
	CreatedAt time.Time `json:"created_at"`
	Enabled   bool      `json:"enabled"`
	Id        string    `json:"id"`

	// Language The language the memory is written in, as a BCP 47 tag detected on this computer (multilingual spec §18), or "" when it is too short to tell. A memory is found in any language; this says which one its text is in.
	Language *string `json:"language,omitempty"`

	// LocalOnly `local_only` keeps the memory on this computer: work that uses it is never sent to a paired computer (§63).
	LocalOnly  bool      `json:"local_only"`
	SourceRef  *string   `json:"source_ref,omitempty"`
	SourceType string    `json:"source_type"`
	UpdatedAt  time.Time `json:"updated_at"`
}

// MemoryList What the assistant remembers, and the categories there are.
type MemoryList struct {
	Categories []string `json:"categories"`
	Memories   []Memory `json:"memories"`
}

// Message A chat message.
type Message struct {
	Content        string    `json:"content"`
	ConversationId string    `json:"conversation_id"`
	CreatedAt      time.Time `json:"created_at"`
	Id             string    `json:"id"`

	// Meta What an assistant answer used and did.
	Meta *MessageMeta `json:"meta,omitempty"`

	// ParentId The message this one follows (#447), or "" for the chat's first.
	ParentId *string `json:"parent_id,omitempty"`
	Role     string  `json:"role"`

	// Versions The versions of this point in the chat, when a retry or an edit made more than one.
	Versions *struct {
		Count int      `json:"count"`
		Ids   []string `json:"ids"`

		// Index This one's place, from 1.
		Index int `json:"index"`
	} `json:"versions,omitempty"`
}

// MessageMeta What an assistant answer used and did.
type MessageMeta struct {
	// Automation An automation a chat drafted from a request. A client shows it and, when the person confirms, creates it with POST /api/v1/automations, passing ID as draft_id and the conversation as conversation_id; creating the same draft again returns that automation.
	Automation *AutomationDraft `json:"automation,omitempty"`

	// AutomationRun The automation run a chat message came from.
	AutomationRun *AutomationRun `json:"automation_run,omitempty"`

	// Backend `backend` and Device ran the answer, such as vulkan and "AMD Radeon RX 7900 XTX", or cpu and "" (#317, contract 1.8), so a client such as the iPhone app can say whether it came from the GPU. Empty when not known, such as when a step ran on a paired computer.
	Backend *string `json:"backend,omitempty"`

	// Context How a turn used the model's context window, in tokens.
	Context *ContextUsage `json:"context,omitempty"`

	// Contract The client contract the metadata was written in (§68). Metadata saved before the contract existed has none, and reads as 1.0.
	Contract *string `json:"contract,omitempty"`

	// Deliberation How the answer was reached when its profile deliberates: the drafts compared and the outcome (#459, contract 1.23).
	Deliberation *struct {
		// Critiques Each draft checked by another drafter, when the drafts disagreed or were too long to compare (contract 1.24).
		Critiques *[]struct {
			Claims        *[]string `json:"claims,omitempty"`
			Critic        string    `json:"critic"`
			Disagreements *[]string `json:"disagreements,omitempty"`

			// Draft The index of the draft checked; Critic the drafter's role.
			Draft        int       `json:"draft"`
			Failed       *bool     `json:"failed,omitempty"`
			LikelyErrors *[]string `json:"likely_errors,omitempty"`
		} `json:"critiques,omitempty"`
		Drafts []struct {
			Chosen *bool `json:"chosen,omitempty"`
			Failed *bool `json:"failed,omitempty"`

			// Final Its short final answer, when it gave one.
			Final   *string `json:"final,omitempty"`
			ModelId *string `json:"model_id,omitempty"`
			NodeId  *string `json:"node_id,omitempty"`

			// NodeName The computer it ran on, for people.
			NodeName *string `json:"node_name,omitempty"`

			// Role The turn's own role for the first draft, then drafter:2…
			Role string `json:"role"`

			// Text The draft, cut to a few thousand characters.
			Text *string `json:"text,omitempty"`
		} `json:"drafts"`

		// Final The final answer kept, when there was one.
		Final *string `json:"final,omitempty"`

		// Judge `judge` wrote the answer from the drafts and critiques, when it did (contract 1.24). Then no draft is chosen.
		Judge *struct {
			ModelId  *string `json:"model_id,omitempty"`
			NodeId   *string `json:"node_id,omitempty"`
			NodeName *string `json:"node_name,omitempty"`
			Role     string  `json:"role"`
		} `json:"judge,omitempty"`

		// Outcome Agreed (every draft gave the same short final answer), majority (most did), disagreed (no answer had a majority), or long (the answers weren't short, so there was nothing to compare).
		Outcome string `json:"outcome"`
	} `json:"deliberation,omitempty"`
	Device *string `json:"device,omitempty"`

	// Files Attached to a question or produced with an answer.
	Files *[]FileRef `json:"files,omitempty"`

	// Notice `notice` tells the user something changed that may affect the answer, such as a smaller model answering after the chosen one failed.
	Notice *string `json:"notice,omitempty"`

	// Reasoning How long a reasoning model thought before it answered, and what it thought (#701, contract 1.43).
	Reasoning *struct {
		// Ms How long it thought, in milliseconds.
		Ms int64 `json:"ms"`

		// Text What it thought, cut at 20,000 characters; empty when the model didn't say.
		Text *string `json:"text,omitempty"`
	} `json:"reasoning,omitempty"`

	// RunId `run_id` names the run trace behind the answer (§35), at GET /api/v1/runs/{id}.
	RunId *string `json:"run_id,omitempty"`

	// Setup Offers to install a missing ability, such as image generation, and to finish the request once it is ready.
	Setup   *SetupOffer     `json:"setup,omitempty"`
	Sources *[]Citation     `json:"sources,omitempty"`
	Steps   *[]ActivityStep `json:"steps,omitempty"`
}

// Model A catalog or installed model.
type Model struct {
	// Capabilities Describes model features.
	Capabilities struct {
		Coding bool `json:"coding"`

		// ToolCallSupport native | compatible | limited | unsupported
		ToolCallSupport *string `json:"tool_call_support,omitempty"`
		ToolCalling     bool    `json:"tool_calling"`
		Vision          bool    `json:"vision"`
	} `json:"capabilities"`
	Context     *int   `json:"context,omitempty"`
	DisplayName string `json:"display_name"`

	// Dynamic installed from browse-all / URL
	Dynamic *bool   `json:"dynamic,omitempty"`
	Family  *string `json:"family,omitempty"`

	// Fit Describes how well a model fits a node's hardware.
	Fit         *ModelFit `json:"fit,omitempty"`
	Id          string    `json:"id"`
	Installed   bool      `json:"installed"`
	InstalledOn *[]struct {
		NodeId   string `json:"node_id"`
		NodeName string `json:"node_name"`
	} `json:"installed_on,omitempty"`

	// Languages How well the model writes each language it has a level for (§13–14, §31), best first.
	Languages *[]struct {
		// Confidence `confidence` in the level: "low", "medium", or "high".
		Confidence string `json:"confidence"`

		// Language A BCP 47 tag, such as "de" or "zh-Hans".
		Language string `json:"language"`

		// Level "limited", "fair", "good", or "excellent".
		Level string `json:"level"`

		// Sources `sources` the level comes from: "model_card", "maintainer", "benchmark", "provider", "community", or "local_evaluation".
		Sources []string `json:"sources"`
	} `json:"languages,omitempty"`
	LastUsedAt        *time.Time `json:"last_used_at,omitempty"`
	MemoryNeededBytes *int64     `json:"memory_needed_bytes,omitempty"`

	// Parameters e.g. "14B"
	Parameters       *string   `json:"parameters,omitempty"`
	Purpose          *[]string `json:"purpose,omitempty"`
	RecommendedRoles *[]string `json:"recommended_roles,omitempty"`
	Runtime          *[]string `json:"runtime,omitempty"`
	SizeBytes        *int64    `json:"size_bytes,omitempty"`

	// Source Describes where a model artifact comes from.
	Source *struct {
		Format *string `json:"format,omitempty"`
		Sha256 *string `json:"sha256,omitempty"`
		Url    string  `json:"url"`
	} `json:"source,omitempty"`

	// Status available|downloading|installed|loading|running|stopping|error
	Status  *string `json:"status,omitempty"`
	Summary *string `json:"summary,omitempty"`

	// SupportRole `support_role` marks a model that serves Yggdrasil instead of chatting: SupportEmbedding, SupportReranker, or SupportClassifier. Empty for chat models.
	SupportRole *string `json:"support_role,omitempty"`

	// Tags coding, general, reasoning, vision, fast, large
	Tags    *[]string `json:"tags,omitempty"`
	Variant *string   `json:"variant,omitempty"`
}

